            notes.append('Table 2 "no flowering yet" (printed across site columns A-D; sites where seedlings were marked not stated); flowering recorded for eight years after first observation')
        else:
            m=re.fullmatch(r'\*?(\d+)(?:\((\d+)\))?',v); assert m,v
            d['Age at first flower production from seed_repr3']=m.group(1)
