        notes.insert(0,'Table 2, p. 342; years to first flowering of marked seedlings after fire')
        if glen:
            d.update(GL); notes.append(GLN)
            if glv: notes.append(f'Glenorie vicinity (all flowering within about 30 m of transect, includes plants unaffected by fire, not only seedlings): {glv} years')
        else:
            d.update(BW); d['Location_name']=site; notes.append(BWN)
            if bwv: notes.append(f'Brisbane Water vicinity (all flowering within about 30 m of transects, includes plants unaffected by fire, not only seedlings): {bwv} years')
        if fnote: notes.append(fnote)
        if g=='Poranthera': notes.append('Results text names Poranthera microphylla with one year; Table 1 and 2 print P. ericifolia')
        if g=='Platysace': notes.append('Platysace linearifolia resprouted at ground level after the low-intensity July-August 1980 fire at site A')
        d['Notes']='; '.join(notes); return d
    if vals[0]=='no flowering yet':
        d=mk(None,vals[0],False); d['Location_name']=' / '.join(sites); rows.append(d); continue
    for i,s in enumerate(sites):
        if vals[i]: rows.append(mk(s,vals[i],False))
    if vals[5]: rows.append(mk('Glenorie',vals[5],True))
    if not any(vals[i] for i in (0,1,2,3,5)): print('NO SITE VALUE',name,vals)
if __name__=='__main__':
    for d in random.sample(rows,3): print({k:v for k,v in d.items() if k not in('Source','Notes')}, d['Notes'][:200]); print()
    print(len(rows))
    if 'write' in sys.argv:
        add_rows(rows); print('written',count(stem))
EOF
