import re, random, sys
from h import *
stem='Knox & Clarke 2004 Cunninghamia_primary juvenile period'
txt=open(f'data/papers_test/md_agents/{stem}.md',encoding='utf-8').read()
def table(after):
    lines=txt[txt.index(after):].split('\n'); out=[]; st=False
    for l in lines:
        if l.startswith('|'): st=True; out.append([c.strip() for c in l.strip().strip('|').split('|')])
        elif st: break
    return out[2:]
t1={r[0]:r for r in table('**Table 1.')}
t2=table('**Table 2.')
def name(s):
    s=s.replace('*','').strip(); p=s.split()
    g=p[0]; rest=p[1:]
    sub=''
    for rk in ('subsp.','var.'):
        if rk in rest: i=rest.index(rk); sub=' '.join(rest[i:]); rest=rest[:i]
    return g,' '.join(rest),sub
def tv(v):
    v=v.strip()
    if v in ('\\*','*','n.a.'): return ''
    m=re.fullmatch(r'Not flowering after ([\d.]+) years',v)
    if m: return '>'+m.group(1)
    m=re.fullmatch(r'<\s*([\d.]+) years',v)
    if m: return '<'+m.group(1)
    m=re.fullmatch(r'([\d.]+) years',v); assert m,v
    return m.group(1)
SRC='Knox, K. J. E., & Clarke, P. J. (2004). Fire response syndromes of shrubs in grassy woodlands in the New England Tableland Bioregion. Cunninghamia, 8(3), 348–353.'
SITE='Imbota Nature Reserve / Booroolong Nature Reserve'
SN=('Table 2, p. 351; data not split by reserve, species site not stated; Imbota NR experimental burns Spring 1999, average yearly rainfall 790 mm (Armidale); '
    'Booroolong NR experimental burns Autumn 2000, average yearly rainfall 884 mm (Guyra); fire intensity not measured, low and moderate intensity expected from low and high fuel loads; '
    'primary juvenile period from naturally recruiting populations and seed sown in the field')
rows=[]
for r in t2:
    g,sp,sub=name(r[0]); fr=r[1]
    d=dict(Genus=g,Species=sp,subsp=sub,scientific_name=f'{g} {sp}',Family='',Source=SRC,File_name=stem,Location_name=SITE,
           Fire_type='experimental burn',Fire_season_categorical='Autumn/Spring')
    d['fire_response categorical_surv1']={'resprouter':'resprouter','obligate seeder':'obligate'}[fr]
    notes=[SN]
    if r[0] in t1:
        a=t1[r[0]]; assert a[1]==fr,(a,r)
        if a[4]!='n.a.': d['resprouter_type']=a[4]
        notes.append(f'Table 1, p. 350: survival {a[2]}% (n = {a[3].strip("()")}) after 100% leaf scorch')
    else: notes.append('not in Table 1; fire response from Table 2')
    d['primary_juvenile_period']=tv(r[2]); d['secondary_juvenile_period']=tv(r[3])
    if d['secondary_juvenile_period']: d['Time_unit']='years'
    if g=='Indigofera' and sp=='australis': notes.append('Discussion states primary juvenile period "appears to be more than four years"; Table 2 and Results give 4 years')
    if sp=='setulosai': notes.append('species epithet as printed (setulosai)')
    d['Notes']='; '.join(notes); rows.append(d)
if __name__=='__main__':
    for d in random.sample(rows,3): print({k:v for k,v in d.items() if k not in('Source','Notes') and v}, d['Notes'][-120:]); print()
    print(len(rows))
    if 'write' in sys.argv: add_rows(rows); print('written',count(stem))
EOF
