def find(name,loc): 
    m=[d for d in rows_out if d['scientific_name']==name and d['Location_name']==loc]; assert len(m)==1,(name,loc,len(m)); return m[0]
def move(name, cols, site, textnote):
    j=find(name,J); s=find(name,site)
    for c in cols:
        s[c]=j.pop(c)
        if c==SJ: s['Time_unit']=j.pop('Time_unit')
    s['Notes']+=f'; {textnote}'
    j['Notes']+=f'; {", ".join(cols)} moved to {site} row (text attributes the value to that catchment)'
    if not any(j.get(c) for c in (R3A,R3,PJ,SJ)): rows_out.remove(j)
# Xanthorrhoea: text p. 137 gives flowering per catchment
for name,nl,lcr,nlt,lct in (('Xanthorrhoea arborea','35','51','35–38 weeks','51–56 weeks'),('Xanthorrhoea media','17','39','17–21 weeks','39–43 weeks')):
    j=find(name,J); j.pop(R3A)
    j['Notes']=j['Notes'].replace(f'; {R3A} converted from {nl} weeks','')+f'; first flowering Resp printed "{nl}w,{lcr}w": split by catchment per text p. 137, values on site rows'
    for site,v,t in ((NL,nl,nlt),(LCR,lcr,lct)):
        s=find(name,site); s[R3A]=years(v,'w')
        s['Notes']+=f'; {R3A} converted from {v} weeks; Appendix 1 first flowering Resp printed "{nl}w,{lcr}w"; text p. 137: flowered {t} after the fires in this catchment'
move('Podocarpus spinulosus',[R3A,SJ],LCR,'text p. 136: resprouted plants in the Lane Cove River area first flowered October 1995, mature fruit by early December 1995 (c. 100 weeks)')
move('Hakea dactyloides',[PJ],LCR,'text p. 138: Lane Cove River area, approximately 6.5 years after the fires to produce a few fruits')
move('Persoonia lanceolata',[R3],LCR,'text p. 138: at one site in the Lane Cove River area seedlings first flowered January 1996, no fruit by June 1996')
for d in rows_out:
    if d['scientific_name']=='Leptospermum trinervium' and d['Location_name']==J: d['Notes']+='; text p. 138: one plant in the Narrabeen Lagoon area flowered 17 weeks (May 1994) after the fires'
    if d['scientific_name']=='Persoonia pinifolia' and d['Location_name']==J: d['Notes']+='; text p. 139: post-fire seedlings first observed after 124 weeks in the Lane Cove River area'
if __name__=='__main__':
    print(len(rows_out))
    for d in rows_out:
        if d['Genus'] in ('Xanthorrhoea','Podocarpus') or d['scientific_name'] in ('Hakea dactyloides',):
            print({k:v for k,v in d.items() if v and k in ('scientific_name','Location_name',R3A,R3,PJ,SJ,'Time_unit','fire_response categorical_surv1')})
    if 'write' in sys.argv: add_rows(rows_out); print('written',count(stem))
