    keys=[k for k in list(ds[0]['_a'])+list(ds[0]['_b']) if k not in ('_page','Species')]
    diff=[k for k in keys if len({(d['_a'].get(k) if k in d['_a'] else d['_b'].get(k)) for d in ds})>1]
    for d in ds: d['_n'][0]+=f' ({len(ds)} entries for this taxon; differ in: {", ".join(diff) if diff else "nothing but position"})'
for d in rows:
    d['Notes']='; '.join(d.pop('_n')); d.pop('_a'); d.pop('_b')
if __name__=='__main__':
    print(len(rows)); print('odd',len(odd),odd[:60])
    random.seed(7)
    for d in random.sample(rows,3): print({k:v for k,v in d.items() if v and k not in ('Source','File_name')})
    for d in rows:
        if d['Notes'].startswith('separate'): print(d['scientific_name'],d['subsp'],d['fire_response categorical_surv1'],'|',d['Notes'][:200])
    if 'write' in sys.argv: add_rows(rows); print('written',count(stem))
